from __future__ import annotations


def merge_profile(record, profile):
    merged = dict(record)
    profile = profile or {}
    # A present-but-null request value is just as incomplete as an absent one.
    for field_name in ("timezone", "currency"):
        if merged.get(field_name) is None:
            merged[field_name] = profile.get(field_name)
    return merged

